}

edits.replace:
export function validateCaseConverterInput(i: CaseConverterInput, lang: "en" | "es" = "en"): string | null {
  if (!i.text) return lang === "es" ? "Ingresa texto para convertir." : "Enter text to convert.";
  return null;
}
